const t={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"안전한 조건-실행 규칙으로 프린터를 자동화하세요. 기본은 꺼짐 - 각 규칙은 직접 활성화하세요."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"아직 규칙이 없습니다. 아래에서 하나 추가한 뒤 준비되면 활성화하세요."}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"규칙 엔진 켜짐"}},off:{t:0,b:{t:2,i:[{t:3}],s:"규칙 엔진 꺼짐"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"켜기"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"끄기"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"엔진과 해당 규칙이 모두 켜져야 실행됩니다."}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"출력이 끝났을 때"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"프린터에 오류가 났을 때"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"히터 온도가 다음 값을 넘었을 때"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"히터 온도가 다음 값 아래로 내려갔을 때"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"알림 기록"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code 명령 실행"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"활성화됨"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"비활성화됨"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"편집"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"삭제"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"규칙 삭제"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"규칙 이름"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"예: 출력 후 히터 끄기"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"조건 (트리거)"}},action:{t:0,b:{t:2,i:[{t:3}],s:"실행 (동작)"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"히터"}},value:{t:0,b:{t:2,i:[{t:3}],s:"온도 (°C)"}},message:{t:0,b:{t:2,i:[{t:3}],s:"메시지"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"규칙 로그에 표시됩니다"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"예: TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"규칙 저장"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"취소"}},add:{t:0,b:{t:2,i:[{t:3}],s:"규칙 추가"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"최근 활동"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"알림됨"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"G-code 실행됨"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"건너뜀 (프린터 사용 중)"}},error:{t:0,b:{t:2,i:[{t:3}],s:"오류"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"가이드"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"규칙 엔진 가이드"}},close:{t:0,b:{t:2,i:[{t:3}],s:"닫기"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"규칙 엔진이란?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"프린터를 감시하다가 설정한 조건이 충족되면 동작을 실행합니다 - 예를 들어 출력이 끝났을 때 메모를 기록하거나 히터를 끕니다. 각 규칙은 '조건이면(트리거) 실행한다(동작)' 형태입니다."}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"안전성 확보 방식"}},body:{t:0,b:{t:2,i:[{t:3}],s:"엔진은 기본적으로 꺼져 있고 모든 규칙은 개별로 활성화해야 하므로 예기치 않게 실행되지 않습니다. 규칙은 조건이 처음 참이 될 때 한 번만 실행됩니다. G-code 동작은 프린터가 대기 중일 때만 실행되고 출력 중에는 거부되며, 모든 결과가 기록됩니다."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"용어집"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"트리거"}},def:{t:0,b:{t:2,i:[{t:3}],s:"규칙을 시작하는 조건. 예: 출력 완료 또는 히터가 특정 온도를 넘는 것."}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"동작"}},def:{t:0,b:{t:2,i:[{t:3}],s:"규칙이 실행될 때 하는 일: 알림 기록 또는 G-code 명령 실행 (대기 중일 때만)."}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"활성화됨"}},def:{t:0,b:{t:2,i:[{t:3}],s:"켜져 있는 규칙. 비활성화된 규칙은 유지되지만 실행되지 않습니다."}}}}}}};export{t as default};
